-- Biochemistry Ch1: Amino Acids, Peptides, and Proteins — BATCH 1 (Structure, Stereochemistry, Side-Chain Classification)
-- discipline=biochemistry, foundation=1A. Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'Amino Acids, Peptides, and Proteins' AND subtopic IN ('Amino Acid Structure & Stereochemistry', 'Side-Chain Classification', 'Hydrophobicity & Unique Residues');

-- Q1 [Amino Acid Structure & Stereochemistry] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Amino Acid Structure & Stereochemistry', 'A chemist comparing the 20 proteinogenic amino acids notes that they share an identical backbone and diverge only at the side chain. In this shared backbone, the \(\alpha\)-carbon of every amino acid is bonded to which set of four groups?', '[{"label": "A", "text": "Amino group, carboxyl group, hydrogen, and R-group"}, {"label": "B", "text": "Amino group, carboxyl group, and R-group only"}, {"label": "C", "text": "Amino group, phosphate group, hydrogen, and R-group"}, {"label": "D", "text": "Amino group, carboxyl group, and two R-groups"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because every standard amino acid is built on one shared backbone: a central \(\alpha\)-carbon bonded to an amino group, a carboxyl group, a single hydrogen atom, and a variable R-group (side chain). LibreTexts states that \"the alpha carbon is also attached to a hydrogen atom and to one additional group\" and that the 20 common amino acids \"differ only in the R-group position\" (5101–5106), and OpenStax describes the \(\alpha\)-carbon as \"bonded to an amino group, a carboxyl group, and to a hydrogen atom\" plus \"another atom or group of atoms... known as the R group\" (4234–4238). Because the first three groups are constant, it is the fourth substituent — the R-group — that distinguishes one amino acid from another. (Choice A) is correct: it lists exactly the four groups the textbook attaches to the \(\alpha\)-carbon — amino, carboxyl, hydrogen, and R-group. (Choice B) drops the hydrogen atom, but the texts explicitly attach a hydrogen to the \(\alpha\)-carbon, giving four substituents, not three. (Choice C) swaps the carboxyl group for a phosphate group; the conserved acidic group on the backbone is a carboxylic acid, and phosphate appears only when a side-chain \(-\text{OH}\) is later phosphorylated, never on the backbone \(\alpha\)-carbon. (Choice D) duplicates the R-group, but only one variable side chain is attached; the other three positions are the fixed amino, carboxyl, and hydrogen groups. This is a Knowledge of Scientific Concepts and Principles question because you must recall the general structure of an \(\alpha\)-amino acid and the four groups bonded to its \(\alpha\)-carbon.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 60)
  RETURNING id
)
