-- Q3 [Amino Acid Structure & Stereochemistry] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Amino Acid Structure & Stereochemistry', 'A pre-med student examines the \(\alpha\)-carbon of alanine and notes that it is a chiral center, which is why alanine is optically active. The student is asked to identify the structural feature that makes this \(\alpha\)-carbon chiral. Which feature correctly accounts for the chirality of the \(\alpha\)-carbon?', '[{"label": "A", "text": "It bears a carbon-carbon double bond"}, {"label": "B", "text": "It has three different groups attached"}, {"label": "C", "text": "It has four different groups attached"}, {"label": "D", "text": "Its side chain is always nonpolar"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the \(\alpha\)-carbon of a standard amino acid is bonded to four different groups — an \(-\text{NH}_3^+\) (amino) group, a \(-\text{COO}^-\) (carboxyl) group, a hydrogen atom, and a distinct side chain (R group) — and a carbon carrying four different substituents is an asymmetric (chiral) center. OpenStax describes amino acids as having "a central asymmetric carbon to which an amino group, a carboxyl group, a hydrogen atom, and a side chain (R group) are attached," and explicitly states that to be enantiomers "a molecule must have at least four different atoms or groups connected to a central carbon." LibreTexts adds that "the amino acids are all chiral except glycine, whose side chain is H," confirming that when the four attached groups are all different the molecule is chiral and optically active. (Choice A) is incorrect: a carbon-carbon double bond produces geometric (cis-trans) isomers, which OpenStax classifies as a different arrangement of atoms "around a double bond," not the source of chirality at a tetrahedral center. (Choice B) is incorrect: OpenStax names the "at least three different atoms or groups" statement as the false threshold; three different groups means two substituents are identical, so the carbon is superimposable on its mirror image and is achiral. (Choice C) is correct: four different groups on the \(\alpha\)-carbon make it asymmetric, so the molecule is not superimposable on its mirror image and is optically active. (Choice D) is incorrect: the side chain need not be nonpolar — glycine''s R group is simply H (making it achiral), while serine, threonine, and cysteine carry polar side chains and lysine and arginine carry charged ones, so "always nonpolar" is false and is not what creates chirality. This is a Scientific Reasoning and Problem Solving question because you must apply the four-different-groups rule for an asymmetric center to explain why the amino acid \(\alpha\)-carbon is chiral.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
