-- Q4 [Amino Acid Structure & Stereochemistry] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Amino Acid Structure & Stereochemistry', 'A researcher resolves a racemic mixture of a standard amino acid into separate enantiomers that rotate plane-polarized light in opposite directions. When she repeats the procedure with one particular proteinogenic amino acid, she CANNOT obtain two distinct enantiomers because its \(\alpha\)-carbon is bonded to only three different groups. Which amino acid is she most likely working with in the second trial?', '[{"label": "A", "text": "Alanine"}, {"label": "B", "text": "Proline"}, {"label": "C", "text": "Serine"}, {"label": "D", "text": "Glycine"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because glycine is the only standard amino acid whose side chain is a single hydrogen atom; its \(\alpha\)-carbon therefore carries two identical hydrogens and only three distinct substituents (\(-\text{NH}_3^+\), \(-\text{COO}^-\), and a hydrogen, with the side-chain H duplicating the existing H), so the \(\alpha\)-carbon is not a stereocenter. The textbook states, "The amino acids are all chiral except glycine, whose side chain is H," and that a chiral molecule "is not superimposable with its mirror image." Because glycine is superimposable on its mirror image, it has no enantiomers and is not optically active, so the resolution described cannot succeed. The other three choices all possess four different groups on the \(\alpha\)-carbon and so exist as resolvable enantiomers. (Choice A) Alanine is the smallest CHIRAL amino acid—its side chain is a methyl group, giving four different substituents on the \(\alpha\)-carbon, so it is optically active and can be resolved. (Choice B) Proline is cyclic (its side chain bonds back to the amino nitrogen to form a five-membered ring), but it still has four distinct groups around the \(\alpha\)-carbon and remains chiral. (Choice C) Serine bears a \(-\text{CH}_2\text{OH}\) side chain and is a polar, chiral amino acid; the textbook explicitly depicts both L-serine and D-serine, confirming it has two enantiomers. (Choice D) is correct: glycine''s \(-\text{H}\) side chain leaves only three different groups on the \(\alpha\)-carbon, making it achiral and not optically active. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that four different groups on a carbon are required for chirality to identify the one standard amino acid that is the exception.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', NULL FROM q
