-- Q5 [Amino Acid Structure & Stereochemistry] hard skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Amino Acid Structure & Stereochemistry', 'A pharmacology student compares the central \(\alpha\)-carbon and optical behavior of the 20 standard proteinogenic amino acids. Consider the following statements:

I. The \(\alpha\)-carbon of a standard amino acid bears an \(\alpha\)-amino group, an \(\alpha\)-carboxyl group, a hydrogen, and a variable R-group.
II. Glycine is the only standard amino acid that is achiral, because its R-group is a hydrogen atom.
III. Every standard amino acid rotates plane-polarized light.

Which of the statements is or are true?', '[{"label": "A", "text": "I only"}, {"label": "B", "text": "III only"}, {"label": "C", "text": "I and III only"}, {"label": "D", "text": "I and II only"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because Statements I and II are both true while Statement III is false. LibreTexts identifies the common structural features of an alpha amino acid as an \"α-amino group, α-carboxylic acid, hydrogen, and a variable R-group\" (LibreTexts §3.1, line 5049), so Statement I is correct. LibreTexts also states, \"The amino acids are all chiral except glycine, whose side chain is H\" (LibreTexts §3.1.7, line 5399), confirming that glycine alone is achiral because its R-group is hydrogen, making Statement II correct. Statement III is false: because glycine is achiral it is not optically active, so it does not rotate plane-polarized light, and the textbook frames rotation of plane-polarized light as a property of chiral (enantiomeric) molecules (line 5404). (Choice A) is incorrect because it omits the true Statement II, which follows directly from the same line that disqualifies Statement III. (Choice B) is incorrect because Statement III is the only false statement; only chiral amino acids rotate plane-polarized light, and achiral glycine does not. (Choice C) is incorrect because it pairs the true Statement I with the false Statement III while dropping the true Statement II about glycine. (Choice D) is correct: Statements I and II are supported verbatim by the textbook, and Statement III fails on the single glycine exception. This is a Knowledge of Scientific Concepts and Principles question because you must recall the four groups bonded to the \(\alpha\)-carbon and the rule that all standard amino acids except achiral glycine are chiral and optically active.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 150)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', NULL FROM q
