-- Q6 [Amino Acid Structure & Stereochemistry] medium skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Amino Acid Structure & Stereochemistry', 'Although every standard amino acid in proteins belongs to the L family, one residue is assigned the \(R\) absolute configuration rather than \(S\) because the sulfur atom in its side chain outranks the \(\alpha\)-carboxyl carbon in the priority ordering used to assign \(R\) and \(S\). Which amino acid is this residue?', '[{"label": "A", "text": "Cysteine"}, {"label": "B", "text": "Methionine"}, {"label": "C", "text": "Serine"}, {"label": "D", "text": "Glycine"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because cysteine is the single standard amino acid that is L in the Fischer sense yet carries the \(R\) absolute configuration. The textbook states that \"all naturally occurring amino acids in proteins are L, which corresponds to the S isomer, except cysteine\" and explains that \"L-cysteine is also (R)-cysteine. Still, all the other L-amino acids are (S), but this reflects the human decision to give a sulfur atom a higher priority than a carbon atom and does not reflect a real difference in configuration\" (LibreTexts 5421, 5458-5462). The sulfur of the \(-\text{SH}\) side chain outranks the carboxyl carbon, flipping the descriptor to \(R\) even though cysteine remains in the L family. (Choice A) is correct: cysteine''s side-chain sulfur raises its priority above the \(\alpha\)-carboxyl carbon, producing the \(R\) label while the residue stays L. (Choice B) Methionine also contains sulfur, but its sulfur sits in a thioether deeper in a nonpolar side chain, not directly at the priority-determining position; methionine remains an \(S\)-configured L-amino acid (LibreTexts 5257-5258). (Choice C) Serine is the oxygen analog of cysteine with a \(-\text{CH}_2\text{OH}\) side chain; oxygen does not outrank the carboxyl carbon in the same way, so L-serine is \(S\) (LibreTexts 5263, 5449). (Choice D) Glycine has a hydrogen side chain, so it is achiral and has no \(R\) or \(S\) descriptor at all (LibreTexts 5399). This is a Knowledge of Scientific Concepts and Principles question because you must recall the structural reason that side-chain sulfur reorders priorities and gives cysteine an \(R\) descriptor within the L family.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
