-- Q8 [Side-Chain Classification] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Side-Chain Classification', 'A researcher sorts the 20 proteinogenic amino acids by the chemical character of their R groups and groups together those whose side chains bear a carboxylic acid functional group and therefore carry a net negative charge at physiological pH. Which pair of amino acids belongs in this acidic group?', '[{"label": "A", "text": "Lysine and arginine"}, {"label": "B", "text": "Asparagine and glutamine"}, {"label": "C", "text": "Aspartate and glutamate"}, {"label": "D", "text": "Serine and threonine"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the acidic side-chain class is defined by side chains carrying a carboxylic acid functional group, and only two amino acids meet this definition. LibreTexts states, "Two amino acids, glutamic acid (glutamate), and aspartic acid (aspartate) constitute the acidic amino acids and contain side chains with carboxylic acid functional groups capable of fully ionizing in solution" (lines 5264-5265). It separately notes that "Proteins contain two amino acids, aspartic acid and glutamic acid, that contain carboxylic acid side chains" (line 3481), and the classification figure groups Aspartate (Asp, D) and Glutamate (Glu, E) under the "Acidic Amino Acids (shown with - charge)" heading (header line 5220; labels lines 5230-5231). (Choice A) is incorrect: lysine and arginine are basic, not acidic — "The basic amino acids, lysine, arginine, and histidine, contain amine functional groups that can be protonated to carry a full charge" (line 5266), so they carry positive, not negative, side-chain charge. (Choice B) is incorrect: asparagine and glutamine are the amide-containing members of the polar uncharged class — "the amide-containing amino acids, glutamine and asparagine" (line 5264) — and despite resembling Asp/Glu in name and one-letter proximity, their amide side chains do not ionize. (Choice C) is correct: aspartate and glutamate are the only two amino acids whose side chains contain a carboxylic acid group, placing them in the acidic class (lines 5264-5265). (Choice D) is incorrect: serine and threonine are hydroxyl-containing members of the polar uncharged class — "the hydroxyl- and sulfhydryl-containing amino acids, serine, threonine, and cysteine" (line 5263) — and their side chains are uncharged. This is a Knowledge of Scientific Concepts and Principles question because you must recall which amino acids constitute the acidic side-chain class.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 70)
  RETURNING id
)
