-- Q9 [Side-Chain Classification] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Side-Chain Classification', 'A researcher sorting the 20 standard amino acids wants to group together every residue whose side chain contains an aromatic ring. Which set of three residues belongs in this group?', '[{"label": "A", "text": "Phenylalanine, tyrosine, tryptophan"}, {"label": "B", "text": "Histidine, tryptophan, proline"}, {"label": "C", "text": "Leucine, isoleucine, valine"}, {"label": "D", "text": "Serine, threonine, cysteine"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the textbook states that "the aromatic amino acids (phenylalanine, tyrosine, and tryptophan) contain an aromatic functional group" in their side chains (LibreTexts 5248). These three residues make up the entire standard aromatic class: phenylalanine carries a benzene ring, tyrosine a phenol (a hydroxyl directly on the ring), and tryptophan a bicyclic indole. (Choice A) is correct: Phe, Tyr, and Trp are exactly the three side chains classified as aromatic (LibreTexts 5248, 5191-5192). (Choice B) is incorrect: although histidine''s imidazole and proline''s 5-membered ring are ring structures, proline is classified as a nonpolar aliphatic amino acid with a "non-aromatic ring structure," and histidine is grouped with the basic amino acids, not the aromatic class (LibreTexts 5244, 5266-5267); only tryptophan in this set is aromatic. (Choice C) is incorrect: leucine, isoleucine, and valine are nonpolar aliphatic residues with "straight or branched hydrocarbon chains," not aromatic rings (LibreTexts 5242). (Choice D) is incorrect: serine, threonine, and cysteine are polar uncharged residues whose side chains contain hydroxyl \(-\text{OH}\) or sulfhydryl \(-\text{SH}\) heteroatoms, not aromatic rings (LibreTexts 5262-5263). This is a Knowledge of Scientific Concepts and Principles question because you must recall which amino acid side chains contain an aromatic ring.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
