-- Q13 [Side-Chain Classification] medium skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Side-Chain Classification', 'A biochemist sorting the 20 standard amino acids by side-chain functional group sets aside two residues whose R-groups are polar yet remain uncharged at physiological pH because each terminates in a carboxamide (amide) group rather than a free carboxylic acid. Which pair of amino acids belongs in this group?', '[{"label": "A", "text": "Asparagine and glutamine"}, {"label": "B", "text": "Aspartate and glutamate"}, {"label": "C", "text": "Serine and threonine"}, {"label": "D", "text": "Lysine and histidine"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because LibreTexts classifies asparagine and glutamine within the polar-uncharged group specifically as ''the amide-containing amino acids, glutamine and asparagine.'' Their side chains carry a carboxamide group, which forms permanent dipoles (the heteroatom criterion for polar-uncharged side chains) but does not ionize at physiological pH, so the residues stay uncharged. The textbook contrasts this directly with the acidic residues, whose side chains carry carboxylic acid groups ''capable of fully ionizing in solution.'' (Choice A) is correct: asparagine (Asn) and glutamine (Gln) are the amide-containing, polar-uncharged pair (LibreTexts 5263-5264). (Choice B) aspartate and glutamate are the carboxylate-bearing acidic residues from which these amides are derived, so they carry a negative side-chain charge rather than a neutral amide (LibreTexts 5264-5265). (Choice C) serine and threonine are polar-uncharged, but their side chains are hydroxyl-containing, not amide-containing (LibreTexts 5263). (Choice D) lysine and histidine are basic residues with amine functional groups that can be protonated to a full positive charge, not neutral amides (LibreTexts 5265-5267). This is a Knowledge of Scientific Concepts and Principles question because you must recall the side-chain classification that identifies asparagine and glutamine as the polar-uncharged amide-containing amino acids.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 100)
  RETURNING id
)
