-- Q14 [Side-Chain Classification] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Side-Chain Classification', 'A biochemist is characterizing the side chains of the standard amino acids and identifies one residue whose side-chain positive charge is delocalized over three nitrogen atoms bonded to a single carbon, a feature that makes it the most basic of the standard residues. Which amino acid does this residue belong to?', '[{"label": "A", "text": "Lysine"}, {"label": "B", "text": "Histidine"}, {"label": "C", "text": "Asparagine"}, {"label": "D", "text": "Arginine"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because the described side chain is the guanidino group of arginine, which has three nitrogen atoms attached to a single carbon (''has 3 N attached to C''), allowing the positive charge to be spread across those nitrogens. The textbook places arginine in the basic class alongside lysine and histidine and assigns it a side-chain \(\text{pK}_\text{a}\) of 12.5, the highest of the standard residues, identifying it as the most basic (and confirming the deprotonated form is a much stronger base than histidine). The chain runs: charge delocalized over three N atoms on one carbon \(\rightarrow\) guanidino group \(\rightarrow\) arginine \(\rightarrow\) basic class. (Choice A) Lysine is genuinely basic, but its side chain carries a single primary amine nitrogen \(-\text{NH}_3^+\), not a charge delocalized over three nitrogens, and its side-chain \(\text{pK}_\text{a}\) of 10.5 is lower, so it is less basic than arginine. (Choice B) Histidine is basic but its side chain is an imidazole ring with two nitrogens, only one of which can accept a proton, and its \(\text{pK}_\text{a}\) of 6.5 makes it the weakest of the three basic residues. (Choice C) Asparagine contains an amide nitrogen whose lone pair is delocalized into the carbonyl by resonance and is therefore not available to accept a proton, so asparagine is polar uncharged rather than basic. (Choice D) is correct: the guanidino side chain with three nitrogens on one carbon belongs to arginine, the most basic standard amino acid. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between a described structural feature and amino acid classification to identify the correct residue.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
