-- Q16 [Side-Chain Classification] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Side-Chain Classification', 'A biochemistry student sorts several amino acids into the side-chain classes used by their textbook. Consider the following proposed assignments:

I. Proline is placed in the nonpolar (aliphatic) class.
II. Cysteine is placed in the polar-uncharged class.
III. Histidine is placed in the acidic class.

Which of the proposed assignments are consistent with the standard side-chain classification?', '[{"label": "A", "text": "I only"}, {"label": "B", "text": "I, II, and III"}, {"label": "C", "text": "I and II only"}, {"label": "D", "text": "II and III only"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because only assignments I and II match the textbook side-chain classes, while III misplaces histidine. The textbook lists the aliphatic (nonpolar) amino acids as glycine, alanine, valine, leucine, isoleucine, and proline, noting that proline''s hydrocarbon side chain has cyclized with the terminal amine but is still classified as aliphatic (LibreTexts 5242-5244), so I is correct. Within the polar uncharged class, the textbook places the sulfhydryl- and hydroxyl-containing serine, threonine, and cysteine, plus the amides glutamine and asparagine (LibreTexts 5263-5264), so II is correct. The textbook explicitly names lysine, arginine, and histidine as the basic amino acids, whose amine groups can be protonated to carry a full charge (LibreTexts 5266); the acidic class contains only aspartate and glutamate (LibreTexts 5264-5265), so III is false. (Choice A) I only is a partial answer that correctly accepts proline but wrongly rejects the valid cysteine assignment in II. (Choice B) I, II, and III incorrectly accepts III, treating basic histidine as acidic. (Choice C) is correct: I and II match the textbook classes while III misclassifies histidine, which is basic, not acidic. (Choice D) II and III only correctly accepts cysteine but wrongly accepts the false histidine assignment while rejecting the valid proline assignment. This is a Scientific Reasoning and Problem Solving question because you must apply the textbook''s side-chain classification rules to evaluate several specific assignments and identify which combination is internally consistent.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
