-- Q17 [Side-Chain Classification] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Side-Chain Classification', 'A biochemist characterizing an enzyme active site identifies a catalytic residue whose side chain carries a five-membered ring containing two nitrogen atoms, one of which holds a lone pair of electrons that remains available to accept a proton. This residue most likely belongs to which amino acid?', '[{"label": "A", "text": "Tryptophan, an aromatic residue"}, {"label": "B", "text": "Proline, a nonpolar residue"}, {"label": "C", "text": "Arginine, a basic residue"}, {"label": "D", "text": "Histidine, a basic residue"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because the described side chain is the imidazole ring of histidine: a five-membered ring with two nitrogen atoms, one tied up in resonance and the other (Nitrogen #3) bearing a lone pair that is available to accept a proton (LibreTexts lines 5280-5282). The textbook places histidine, together with lysine and arginine, in the basic class, which ''contain amine functional groups that can be protonated to carry a full charge'' (LibreTexts line 5266). The structural clue (imidazole) and the class (basic) therefore both point to histidine. (Choice A) Tryptophan also has a nitrogen-containing ring, but it is the bicyclic indole; the textbook explains that indole''s nitrogen lone pair is delocalized into the aromatic pi system and ''is unavailable to accept a proton,'' so tryptophan is aromatic, not basic (LibreTexts lines 5277-5279). (Choice B) Proline does have a five-membered ring, but it is a non-aromatic pyrrolidine-type ring whose side chain has cyclized with the amine, making proline an aliphatic, nonpolar amino acid rather than a basic one (LibreTexts lines 5242-5244). (Choice C) Arginine is correctly basic, but its positively chargeable group is the guanidino group (three nitrogens bonded to a carbon), not an imidazole ring, so it fails the specific structural clue (LibreTexts lines 5266, 5702-5703). (Choice D) is correct: an imidazole side chain with a proton-accepting ring nitrogen identifies histidine, a basic amino acid. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between a described structural feature and amino-acid side-chain classification to identify the residue.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
