WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Hydrophobicity & Unique Residues', 'A biochemist surveying the 20 standard amino acids wants to isolate the two whose side chains incorporate a sulfur atom into the R-group. Which pair of standard amino acids contains sulfur in its side chain?', '[{"label": "A", "text": "Cysteine and serine"}, {"label": "B", "text": "Methionine and cysteine"}, {"label": "C", "text": "Methionine and threonine"}, {"label": "D", "text": "Cysteine and selenocysteine"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because methionine and cysteine are the two standard amino acids whose side chains contain sulfur. The textbook states that ''Methionine, one of the sulfur-containing amino acids, is usually classified as a nonpolar, hydrophobic amino acid. The terminal methyl group is a thioether'' (LibreTexts 5257-5258), while cysteine carries a sulfhydryl \(-\text{SH}\) (thiol) group (LibreTexts 5263). Of the two, cysteine''s thiol is the redox-active one that is readily oxidized: ''Cysteine is a potent nucleophile that often forms a covalent disulfide bond with another Cys'' (LibreTexts 5808). (Choice A) is incorrect because cysteine does contain sulfur, but serine is the oxygen analog — its side chain is the hydroxyl \(-\text{CH}_2\text{OH}\), classified among ''the hydroxyl- and sulfhydryl-containing amino acids, serine, threonine, and cysteine'' where serine is hydroxyl, not sulfhydryl (LibreTexts 5263). (Choice B) is correct: both methionine (thioether) and cysteine (thiol) carry sulfur in the R-group (LibreTexts 5257-5258, 5263). (Choice C) is incorrect because methionine does contain sulfur, but threonine is a hydroxyl-containing (\(-\text{OH}\)) polar amino acid, not a sulfur-containing one (LibreTexts 5263). (Choice D) is incorrect because cysteine contains sulfur, but selenocysteine is not one of the 20 standard amino acids — it is a rare non-standard residue that ''occasionally appear[s] in proteins,'' found in Archaea, eubacteria, and animals (LibreTexts 5118). This is a Knowledge of Scientific Concepts and Principles question because you must recall which standard amino acid side chains contain sulfur.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 105)
  RETURNING id
)
